	if err != nil {
		t.Fatal(err)
	}
	t.Setenv("FAKE_ENGINE_BLOCK", fifo)
	released := false
	release = func() {
		if released {
			return
		}
		released = true
		_, _ = gate.WriteString("go\n")
	}
	t.Cleanup(func() {
