	for _, tt := range []struct {
		name   string
		noBash bool
		shell  string
	}{
		{"bash available", false, "/bin/bash"},
		{"bash missing", true, "/bin/sh"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			fe := installFakeEngine(t)
			if tt.noBash {
